const existingUrls = new Set(
  $('Get Existing URLs').all().map(i => i.json.fields.URL)
);

return items.filter(item => !existingUrls.has(item.json.link));

const articles = $('Filter Top Articles').all();
const summary = articles.map((a, i) =>
  `${i+1}. ${a.json.title} — ${a.json.contentSnippet}`
).join('\n');

return [{ json: { articleList: summary } }];

parameters.text:
=You are an expert email copywriter for {{ $('Get Brand Guidelines').item.json.fields.Company }}.

Tone: {{ $('Get Brand Guidelines').item.json.fields.Tone }}
Audience: {{ $('Get Brand Guidelines').item.json.fields.Audience }}
Writing Style: {{ $('Get Brand Guidelines').item.json.fields.Writing_Style }}
CTA: {{ $('Get Brand Guidelines').item.json.fields.CTA }}
Avoid these words: {{ $('Get Brand Guidelines').item.json.fields.Banned_Words }}

Rules:
- Keep the newsletter under 600 words.
- Use short paragraphs.
- Never invent facts — only reference the article summaries below.
- Include exactly one clear call to action.

Articles:
{{ $json.articleList }}

Return a JSON object with exactly these fields: "subject_options" (an array of exactly 3 subject line strings), "intro" (a string), "sections" (an array of exactly 3 objects, each with "title" and "body" string fields), and "cta" (a string). Use these exact field names.

parameters.jsCode:
return [{
  json: {
    title: $('Wait').item.json.title,
    link: $('Wait').item.json.link,
    contentSnippet: $('Wait').item.json.contentSnippet,
    score: $json.output.score,
    reason: $json.output.reason
  }
}];

const generate = $('Generate Newsletter').item.json.output;
const brand = $('Get Brand Guidelines').item.json.fields;
const recordId = $json.id;

const articlesList = $('Filter Top Articles').all()
  .map(a => '• ' + a.json.title)
  .join('\\n');

return [{
  json: {
    subject: generate.subject_options[0],
    company: brand.Company,
    week: $now.toISODate(),
    articlesList: articlesList,
    intro: generate.intro.replace(/\n/g, '\\n'),
    cta: generate.cta,
    recordId: recordId
  }
}];

